class Solution {
public:
    vector<int> selfDividingNumbers(int left, int right) {
        vector<int> res;
        for (int n = left; n <= right; n++) {
            int temp = n;
            bool valid = true;
            while (temp > 0) {
                int d = temp % 10;
                if (d == 0 || n % d != 0) {
                    valid = false;
                    break;
                }
                temp /= 10;
            }
            if (valid) res.push_back(n);
        }
        return res;
    }
};

class Solution {
    public List<Integer> selfDividingNumbers(int left, int right) {
        List<Integer> res = new ArrayList<>();
        for (int n = left; n <= right; n++) {
            int temp = n;
            boolean valid = true;
            while (temp > 0) {
                int d = temp % 10;
                if (d == 0 || n % d != 0) {
                    valid = false;
                    break;
                }
                temp /= 10;
            }
            if (valid) res.add(n);
        }
        return res;
    }
}

var selfDividingNumbers = function(left, right) {
    const res = [];
    for (let n = left; n <= right; n++) {
        let temp = n;
        let valid = true;
        while (temp > 0) {
            const d = temp % 10;
            if (d === 0 || n % d !== 0) {
                valid = false;
                break;
            }
            temp = Math.floor(temp / 10);
        }
        if (valid) res.push(n);
    }
    return res;
};
